    private final Set<String> posted = ConcurrentHashMap.newKeySet();

    void handle(PaymentEvent e) {
        if (posted.contains(e.idempotencyKey())) return;   // check
        ledger.post(e);                                    // about 80 ms
        posted.add(e.idempotencyKey());                    // act
    }
}

