class PaymentHandler {
    private val posted: MutableSet<String> = ConcurrentHashMap.newKeySet()

    fun handle(e: PaymentEvent) {
        if (e.idempotencyKey in posted) return             // check
        ledger.post(e)                                     // about 80 ms
        posted += e.idempotencyKey                         // act
    }
}

