void handle(PaymentEvent e) {
    // 1. claim the key: add() returns false if it was already there
    if (!posted.add(e.idempotencyKey())) return;
    try {
        ledger.post(e);                           // 2. post
    } catch (RuntimeException ex) {
        posted.remove(e.idempotencyKey());        // 3. release on failure
        throw ex;
    }
}

