fun collide(n: Int, task: () -> Unit) {
    val ready = CountDownLatch(n)
    val go = CountDownLatch(1)
    val threads = List(n) {
        thread {
            ready.countDown()
            try { go.await() } catch (e: InterruptedException) { Thread.currentThread().interrupt(); return@thread }
            task()
        }
    }
    ready.await()      // all parked at the start line
    go.countDown()     // starting gun
    threads.forEach { it.join() }
}
